package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.EnvironmentVO;

@RequiredArgsConstructor
public class EnvironmentValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<EnvironmentVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @param environment
   * @return
   */
  public T environment(EnvironmentVO environment) {
    this.value = Optional.of(environment);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param environment
   * @return
   */
  public T environment(Optional<EnvironmentVO> environment) {
    this.value = environment;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param environment
   * @return
   */
  public T environment(String environment) {
    this.value = Optional.of(EnvironmentVO.from(environment));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T environmentNull() {
    this.value = Optional.of(EnvironmentVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getEnvironment() {
    return value.flatMap(EnvironmentVO::getEnvironment);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<EnvironmentVO> getEnvironmentValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public EnvironmentVO readEnvironment(final Optional<ObservedSource> original,
      final ConstraintFailList fails) {
    return value.orElse(
        original.map(ObservedSource::getEnvironmentValue).orElseGet(EnvironmentVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetEnvironment() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetEnvironmentIfMatches(final String field) {
    if ("environment".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
